import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

// Secret key for signing tokens: prefer environment variable, fallback to cryptographically strong runtime secret
const RUNTIME_SECRET = crypto.randomBytes(32).toString('hex');
export const JWT_SECRET = process.env.JWT_SECRET || RUNTIME_SECRET;

// Token blacklist for revoked sessions upon logout
const revokedTokens = new Set<string>();

// Password Hashing with strong bcrypt (10 rounds)
export async function hashPassword(plainText: string): Promise<string> {
  return await bcrypt.hash(plainText, 10);
}

export function hashPasswordSync(plainText: string): string {
  return bcrypt.hashSync(plainText, 10);
}

export async function comparePassword(plainText: string, hashed: string): Promise<boolean> {
  if (!plainText || !hashed) return false;
  // If database somehow still has unhashed password (migration fallback), check and allow bcrypt upgrade
  if (!hashed.startsWith('$2a$') && !hashed.startsWith('$2b$')) {
    return plainText === hashed;
  }
  return await bcrypt.compare(plainText, hashed);
}

export interface AuthTokenPayload {
  id: number;
  username: string;
  role: string;
  iat?: number;
  exp?: number;
}

// Generate JWT session token with 2-hour expiration
export function generateToken(payload: { id: number; username: string; role: string }): { token: string; expiresIn: number } {
  const expiresIn = 2 * 60 * 60; // 2 hours in seconds
  const token = jwt.sign(payload, JWT_SECRET, { expiresIn: '2h' });
  return { token, expiresIn };
}

// Verify JWT session token
export function verifyToken(token: string): AuthTokenPayload | null {
  if (!token || revokedTokens.has(token)) {
    return null;
  }
  try {
    const decoded = jwt.verify(token, JWT_SECRET) as AuthTokenPayload;
    return decoded;
  } catch {
    return null;
  }
}

// Revoke token upon logout
export function revokeToken(token: string): void {
  if (token) {
    revokedTokens.add(token);
  }
}

// Input Sanitization to prevent XSS (Cross-Site Scripting) and script injection
export function sanitizeInput(input: any): string {
  if (typeof input !== 'string') return '';
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '') // Remove script tags
    .replace(/javascript:/gi, '') // Remove inline javascript protocols
    .replace(/on\w+\s*=/gi, '') // Remove inline event handlers like onclick, onload, onerror
    .replace(/[<>]/g, (c) => (c === '<' ? '&lt;' : '&gt;')) // Escape angle brackets
    .trim();
}

// Strip all HTML tags completely for clean plain-text fields
export function stripHtml(input: any): string {
  if (typeof input !== 'string') return '';
  return input
    .replace(/<[^>]*>/g, '') // Strip all tags
    .replace(/javascript:/gi, '')
    .trim();
}

// Validate and sanitize media/image URLs
export function sanitizeMediaUrl(url: any): string {
  if (typeof url !== 'string') return '';
  const trimmed = url.trim();
  // Safe Base64 Image
  if (trimmed.startsWith('data:image/')) {
    if (
      trimmed.startsWith('data:image/png;base64,') ||
      trimmed.startsWith('data:image/jpeg;base64,') ||
      trimmed.startsWith('data:image/jpg;base64,') ||
      trimmed.startsWith('data:image/webp;base64,') ||
      trimmed.startsWith('data:image/gif;base64,')
    ) {
      return trimmed;
    }
    return '';
  }
  // Safe HTTP/HTTPS image URL
  if (trimmed.startsWith('https://') || trimmed.startsWith('http://')) {
    return trimmed.replace(/[<>"']/g, '');
  }
  return '';
}

// Rate limiter for public endpoints (inquiry submissions, login attempts)
interface RateLimitEntry {
  count: number;
  resetTime: number;
}
const ipRateLimits = new Map<string, RateLimitEntry>();

export function checkRateLimit(ip: string, maxAttempts = 10, windowMs = 60 * 1000): boolean {
  const now = Date.now();
  const entry = ipRateLimits.get(ip);

  if (!entry || now > entry.resetTime) {
    ipRateLimits.set(ip, { count: 1, resetTime: now + windowMs });
    return true;
  }

  if (entry.count >= maxAttempts) {
    return false;
  }

  entry.count++;
  return true;
}
